"""Magias de nível 2. Tradução não oficial do SRD 5.2.1."""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from spell_hl import D, H, T, X

SPELL = {
 "acid_arrow": "Uma flecha verde cintilante dispara contra um alvo no alcance e explode em ácido. Faça um ataque mágico à distância. Se acertar, 4d4 de dano Ácido agora e 2d4 no fim do próximo turno dele. Se errar, só metade do dano inicial." + D("1d4", 2, "O dano (inicial e posterior)"),
 "aid": "Escolha até três criaturas no alcance. Os PV máximos e atuais de cada uma aumentam em 5 pela duração." + X("Mais 5 PV por nível de espaço acima de 2."),
 "alter_self": "Você altera sua forma física com uma opção (troque com a ação Magia durante a duração):\n\nAdaptação Aquática. Guelras e membranas: respira debaixo d'água e ganha Deslocamento de Natação igual ao seu Deslocamento.\nMudar Aparência. Altura, peso, rosto, voz, cabelo, cor e traços, até parecer de outra espécie (sem mudar estatísticas, tamanho ou formato básico).\nArmas Naturais. Garras (Cortante), presas ou chifres (Perfurante) ou cascos (Contundente): seu Golpe Desarmado com elas causa 1d6 e usa seu modificador de conjuração no ataque e no dano.",
 "animal_messenger": "Uma Fera Minúscula que você vê no alcance faz uma salvaguarda de Carisma ou leva uma mensagem sua (ND acima de 0 passa automaticamente). Indique um lugar que já visitou, um destinatário por descrição geral e uma mensagem de até 25 palavras. Ela viaja cerca de 40 km por dia (80 km se voar) e entrega imitando você. Se não chegar antes do fim, a mensagem se perde e ela volta." + X("A duração aumenta em 48 horas por nível de espaço acima de 2."),
 "arcane_lock": "Você toca uma porta, janela, portão, recipiente ou alçapão fechado e o tranca magicamente pela duração; meios não mágicos não o abrem. Você e quem designar abrem normalmente, e você pode definir uma senha que, dita a até 1,5 m, destranca por 1 minuto.",
 "arcanists_magic_aura": "Com um toque, você põe uma ilusão numa criatura voluntária ou num objeto não vestido nem carregado, pela duração (conjurada no mesmo alvo por 30 dias, dura até ser dissipada).\n\nMáscara (criatura). Magias e efeitos a tratam como outro tipo de criatura à sua escolha.\nAura Falsa (objeto). Muda como o objeto aparece a magias como Detectar Magia: não mágico parece mágico, mágico parece comum, ou a escola de magia muda.",
 "augury": "Você recebe de uma entidade um presságio sobre o resultado de algo que planeja fazer nos próximos 30 minutos. O Mestre escolhe: Fortuna (bom), Infortúnio (ruim), Fortuna e infortúnio (bom e ruim) ou Indiferença (nem um nem outro). Não considera circunstâncias que possam mudar o resultado. Cada conjuração extra antes de um Descanso Longo tem 25% cumulativos de chance de não ter resposta.",
 "barkskin": "Você toca uma criatura voluntária. Até a magia acabar, a pele dela parece casca de árvore e sua CA passa a 17, se for menor.",
 "blindness_deafness": "Uma criatura que você vê no alcance faz uma salvaguarda de Constituição ou fica Cega ou Surda (à sua escolha) pela duração, repetindo a salvaguarda no fim de cada turno dela." + T(2),
 "blur": "Seu corpo fica borrado. Pela duração, ataques contra você têm Desvantagem, exceto de quem te percebe com Percepção às Cegas ou Visão Verdadeira.",
 "calm_emotions": "Cada Humanoide numa Esfera de 6 m de raio no alcance faz uma salvaguarda de Carisma. Quem falhar sofre um efeito, à sua escolha por criatura:\n\nImunidade a Enfeitiçado e Amedrontado até a magia acabar (condições atuais ficam suprimidas).\nFica Indiferente a criaturas à sua escolha com quem era Hostil; termina se sofrer dano ou vir aliados sofrendo.",
 "continual_flame": "Uma chama surge de um objeto que você toca, emitindo Luz Plena em 6 m e Penumbra por mais 6 m. Parece fogo comum, mas não esquenta nem consome combustível; pode ser coberta, mas não abafada nem apagada.",
 "darkness": "Pela duração, Escuridão mágica preenche uma Esfera de 4,5 m de raio a partir de um ponto no alcance. Visão no Escuro não enxerga através dela e luz não mágica não a ilumina. Conjurada num objeto, preenche uma Emanação de 4,5 m dele (cobri-lo bloqueia). Dissipa luzes de magias de nível 2 ou menor que se sobreponham.",
 "darkvision": "Pela duração, uma criatura voluntária que você toca tem Visão no Escuro de 45 m.",
 "detect_thoughts": "Ative um efeito agora e, com a ação Magia, em turnos seguintes:\n\nSentir Pensamentos. Você sente a presença de mentes (de quem conhece idiomas ou tem telepatia) a até 9 m, sem lê-las. Bloqueado por 30 cm de pedra, terra ou madeira, 2,5 cm de metal ou chumbo.\nLer Pensamentos. Uma criatura a até 9 m: você sabe o que está mais na mente dela. No próximo turno, com a ação Magia, pode sondar mais fundo: ela faz salvaguarda de Sabedoria; na falha você descobre raciocínio, emoções e algo importante para ela; no sucesso a magia termina. Ela percebe a sondagem e pode usar uma ação para um teste de Inteligência (Arcanismo) contra sua CD para encerrá-la.",
 "dragons_breath": "Você toca uma criatura voluntária e escolhe Ácido, Frio, Fogo, Elétrico ou Veneno. Até a magia acabar, ela pode usar a ação Magia para soprar um Cone de 4,5 m: cada criatura na área faz salvaguarda de Destreza, 3d6 do tipo escolhido na falha, metade no sucesso." + D("1d6", 2),
 "enhance_ability": "Você toca uma criatura e escolhe Força, Destreza, Inteligência, Sabedoria ou Carisma. Pela duração, ela tem Vantagem em testes desse atributo." + T(2, "uma criatura adicional (com atributo diferente, se quiser)"),
 "enlarge_reduce": "Pela duração, aumenta ou reduz uma criatura ou objeto (não vestido nem carregado) que você vê no alcance. Criatura relutante faz salvaguarda de Constituição e, no sucesso, não é afetada. O que ela veste e carrega muda junto; itens soltos voltam ao normal.\n\nAumentar. Uma categoria de tamanho maior, Vantagem em testes e salvaguardas de Força e +1d4 de dano com armas ou Golpes Desarmados.\nReduzir. Uma categoria menor, Desvantagem em testes e salvaguardas de Força e −1d4 de dano (mínimo 1).",
 "enthrall": "Suas palavras distraem: criaturas à sua escolha que você vê no alcance fazem salvaguarda de Sabedoria (quem você ou aliados estão combatendo passa automaticamente). Na falha, têm −10 em Sabedoria (Percepção) e na Percepção Passiva até a magia acabar.",
 "find_steed": "Você invoca um ser de outro mundo como montaria leal num espaço no alcance (substitui a anterior). Parece um animal Grande à sua escolha (cavalo, camelo, lobo atroz, alce) e é Celestial, Fada ou Corruptor.\n\nCombate. Aliada, age na sua Iniciativa e é montaria controlada quando você a monta. Se você ficar Incapacitado, ela age logo após você, protegendo-o.\nDesaparecimento. Some a 0 PV ou se você morrer, deixando o que carregava.\n\nMontaria de Outro Mundo: CA 10 + 1 por nível da magia; PV 5 + 10 por nível; Deslocamento 18 m, Voo 18 m com magia de nível 4+; telepatia com você a até 1,5 km." + X("Use o nível do espaço como nível da magia nas estatísticas."),
 "find_traps": "Você sente armadilhas no alcance e em linha de visão (objetos ou mecanismos feitos para causar dano ou perigo, como Alarme, Glifo de Proteção ou um fosso), não perigos naturais. Revela que há uma armadilha e a natureza geral do perigo, não onde está.",
 "flame_blade": "Você evoca uma lâmina de fogo do tamanho de uma cimitarra na mão livre pela duração. Se soltá-la, some, mas pode evocá-la de novo como Ação Bônus. Com a ação Magia, faça um ataque mágico corpo a corpo: 3d6 + modificador de conjuração de dano de Fogo. Emite Luz Plena em 3 m e Penumbra por mais 3 m." + D("1d6", 2),
 "flaming_sphere": "Você cria uma esfera de fogo de 1,5 m de diâmetro num espaço no chão no alcance. Quem terminar o turno a até 1,5 m dela faz salvaguarda de Destreza: 2d6 de dano de Fogo na falha, metade no sucesso.\n\nComo Ação Bônus, role-a até 9 m; ao entrar no espaço de uma criatura, ela faz a salvaguarda e a esfera para. Passa por barreiras de até 1,5 m e salta fossos de até 3 m. Incendeia objetos inflamáveis e emite Luz Plena em 6 m e Penumbra por mais 6 m." + D("1d6", 2),
 "gentle_repose": "Você toca um cadáver. Pela duração, ele não apodrece nem pode virar Morto-Vivo, e esses dias não contam no prazo de magias como Reviver os Mortos.",
 "gust_of_wind": "Uma Linha de vento forte de 18 m por 3 m sai de você pela duração. Cada criatura nela faz salvaguarda de Força ou é empurrada 4,5 m ao longo da Linha; quem terminar o turno nela repete. Avançar contra o vento custa o dobro de movimento. Dispersa gases, apaga velas e tem 50% de chance de apagar chamas protegidas. Como Ação Bônus, mude a direção.",
 "heat_metal": "Escolha um objeto de metal fabricado (arma, armadura média ou pesada de metal) que você vê no alcance: ele fica em brasa. Quem estiver em contato sofre 2d8 de dano de Fogo ao conjurar e, como Ação Bônus em turnos seguintes, de novo. Quem segura ou veste o objeto e sofre o dano faz salvaguarda de Constituição ou o larga, se puder; se não largar, tem Desvantagem em ataques e testes até o começo do seu próximo turno." + D("1d8", 2),
 "hold_person": "Um Humanoide que você vê no alcance faz uma salvaguarda de Sabedoria ou fica Paralisado pela duração, repetindo no fim de cada turno dele." + T(2, "um Humanoide adicional"),
 "invisibility": "Uma criatura que você toca fica Invisível até a magia acabar. Termina logo depois que ela fizer uma jogada de ataque, causar dano ou conjurar magia." + T(2),
 "knock": "Escolha um objeto que você vê no alcance (porta, caixa, baú, algemas, cadeado). Uma tranca comum, emperramento ou barra se solta (só uma, se houver várias). Tranca Arcana fica suprimida por 10 minutos. Ao conjurar, uma batida alta é ouvida a até 90 m.",
 "lesser_restoration": "Você toca uma criatura e encerra nela uma condição: Cego, Surdo, Paralisado ou Envenenado.",
 "levitate": "Uma criatura ou objeto solto (até 250 kg) que você vê no alcance sobe até 6 m e fica suspenso pela duração. Criatura relutante que passar numa salvaguarda de Constituição não é afetada. O alvo só se move empurrando superfícies, como se escalasse. Você muda a altitude até 6 m por turno (como parte do seu movimento, se for você; senão, com a ação Magia). Ao fim, desce suavemente.",
 "locate_animals_or_plants": "Descreva ou nomeie um tipo de Fera, criatura Planta ou planta não mágica. Você descobre a direção e a distância do mais próximo a até 8 km, se houver.",
 "locate_object": "Descreva ou nomeie um objeto familiar: você sente a direção dele se estiver a até 300 m, e o sentido do movimento se ele se mover. Localiza um objeto específico que já viu de perto (a até 9 m) ou o mais próximo de um tipo. Chumbo no caminho bloqueia.",
 "magic_mouth": "Você implanta uma mensagem de até 25 palavras (falada em até 10 minutos) num objeto que você vê e ninguém carrega, com uma condição de disparo visual ou sonora a até 9 m dele. Quando disparada, uma boca mágica surge no objeto e recita com sua voz. Pode encerrar após falar ou repetir a cada disparo.",
 "magic_weapon": "Você toca uma arma não mágica: até a magia acabar, ela vira mágica com +1 no ataque e no dano. Conjurar de novo encerra a anterior." + X("O bônus vira +2 com espaço de nível 3–5 e +3 com nível 6+."),
 "mind_spike": "Você crava um espinho psiônico na mente de uma criatura que vê no alcance. Salvaguarda de Sabedoria: 3d8 de dano Psíquico na falha, metade no sucesso. Na falha, você também sabe onde ela está até a magia acabar (no mesmo plano): ela não consegue se esconder de você nem se beneficiar de Invisível contra você." + D("1d8", 2),
 "mirror_image": "Três duplicatas ilusórias suas surgem no seu espaço e imitam você. Sempre que um ataque te acertar, role um d6 por duplicata restante; se algum der 3 ou mais, uma duplicata é atingida e destruída no seu lugar. Termina quando as três forem destruídas. Não afeta criaturas Cegas ou com Percepção às Cegas ou Visão Verdadeira.",
 "misty_step": "Envolto por uma névoa prateada, você se teleporta até 9 m para um espaço desocupado que vê.",
 "moonbeam": "Um raio de luz prateada desce num Cilindro de 1,5 m de raio e 12 m de altura centrado num ponto no alcance, com Penumbra. Com a ação Magia, mova-o até 18 m.\n\nAo surgir, cada criatura nele faz salvaguarda de Constituição: 2d10 de dano Radiante na falha (e quem estiver transformado volta à forma verdadeira e não muda de forma enquanto estiver nele), metade no sucesso. Também faz a salvaguarda quando o Cilindro chega a ela, quando entra ou termina o turno nele (uma vez por turno)." + D("1d10", 2),
 "pass_without_trace": "Você emana uma aura ocultadora numa Emanação de 9 m pela duração. Você e criaturas à sua escolha nela têm +10 em Destreza (Furtividade) e não deixam rastros.",
 "phantasmal_force": "Uma criatura que você vê no alcance faz salvaguarda de Inteligência. Na falha, você cria na mente dela um objeto, criatura ou fenômeno ilusório de até um Cubo de 3 m, com som, temperatura e outros estímulos, que só ela percebe. Com a ação Estudar e um teste de Inteligência (Investigação) contra sua CD, ela percebe a ilusão e a magia termina.\n\nEla trata o fantasma como real e racionaliza resultados ilógicos. Se ele representar algo perigoso, pode causar 2d8 de dano Psíquico a cada turno seu se ela estiver na área ou a até 1,5 m.",
 "prayer_of_healing": "Até cinco criaturas à sua escolha que fiquem no alcance durante toda a conjuração recebem os benefícios de um Descanso Curto e recuperam 2d8 PV. Cada uma só pode ser afetada de novo após um Descanso Longo." + H("1d8", 2),
 "protection_from_poison": "Você toca uma criatura e encerra a condição Envenenado. Pela duração, ela tem Vantagem em salvaguardas contra ficar Envenenada e Resistência a dano de Veneno.",
 "ray_of_enfeeblement": "Um raio enfraquecedor atinge uma criatura no alcance, que faz salvaguarda de Constituição. No sucesso, tem Desvantagem no próximo ataque até o começo do seu próximo turno. Na falha, tem Desvantagem em Testes de d20 de Força pela duração e subtrai 1d8 de todas as jogadas de dano, repetindo a salvaguarda no fim de cada turno dela.",
 "rope_trick": "Você toca uma corda; uma ponta sobe até ficar vertical ou tocar um teto. No topo, um portal Invisível de 90 cm por 1,5 m leva a um espaço extradimensional para até oito criaturas Médias ou menores, alcançado pela corda (que pode ser puxada para dentro). Ataques e magias não entram nem saem, mas de dentro se vê através do portal. Ao fim, tudo cai para fora.",
 "scorching_ray": "Você arremessa três raios de fogo, num alvo ou em vários no alcance. Um ataque mágico à distância por raio; cada acerto causa 2d6 de dano de Fogo." + X("Um raio a mais por nível de espaço acima de 2."),
 "see_invisibility": "Pela duração, você vê criaturas e objetos Invisíveis como se fossem visíveis e enxerga o Plano Etéreo, onde tudo parece fantasmagórico.",
 "shatter": "Um estrondo irrompe num ponto no alcance. Cada criatura numa Esfera de 3 m de raio faz salvaguarda de Constituição: 3d8 de dano Trovejante na falha, metade no sucesso (Constructos com Desvantagem). Objetos não mágicos soltos na área também sofrem o dano." + D("1d8", 2),
 "shining_smite": "O alvo atingido sofre 2d6 extra de dano Radiante. Até a magia acabar, ele emite Luz Plena em 1,5 m, ataques contra ele têm Vantagem e ele não se beneficia de Invisível." + D("1d6", 2),
 "silence": "Pela duração, nenhum som é criado ou atravessa uma Esfera de 6 m de raio num ponto no alcance. Quem estiver totalmente dentro tem Imunidade a dano Trovejante e fica Surdo, e não é possível conjurar magias com componente Verbal ali.",
 "spider_climb": "Até a magia acabar, uma criatura voluntária que você toca anda por superfícies verticais e tetos com as mãos livres e ganha Deslocamento de Escalada igual ao seu Deslocamento." + T(2),
 "spike_growth": "O chão numa Esfera de 6 m de raio no alcance cria espinhos duros e vira Terreno Difícil pela duração. Quem se mover na área sofre 2d4 de dano Perfurante a cada 1,5 m. O terreno parece natural: quem não viu a conjuração precisa da ação Procurar e um teste de Sabedoria (Percepção ou Sobrevivência) contra sua CD para notá-lo.",
 "spiritual_weapon": "Você cria uma força espectral flutuante em forma de arma num espaço no alcance e faz na hora um ataque mágico corpo a corpo contra uma criatura a até 1,5 m dela: 1d8 + modificador de conjuração de dano de Energia. Como Ação Bônus em turnos seguintes, mova-a até 6 m e repita o ataque." + D("1d8", 2),
 "suggestion": "Você sugere uma atividade (até 25 palavras) a uma criatura que você vê no alcance e que te ouve e entende. Precisa parecer viável e não causar dano óbvio a ela ou aliados. Ela faz salvaguarda de Sabedoria ou fica Enfeitiçada pela duração (ou até você ou aliados a ferirem) e segue a sugestão como puder; se a terminar antes, a magia acaba para ela.",
 "warding_bond": "Você toca outra criatura voluntária e cria um vínculo místico até a magia acabar. Enquanto ela estiver a até 18 m, ganha +1 na CA e nas salvaguardas e Resistência a todo dano, mas cada dano que ela sofrer você também sofre. Termina se você cair a 0 PV, se vocês se separarem por mais de 18 m ou se for conjurada de novo em um de vocês.",
 "web": "Você conjura teias pegajosas que enchem um Cubo de 6 m num ponto no alcance: Terreno Difícil e Levemente Obscurecido. Sem ancoragem entre duas massas sólidas ou sobre uma superfície, a teia desaba no começo do seu próximo turno.\n\nQuem entrar nas teias pela primeira vez no turno ou começar o turno nelas faz salvaguarda de Destreza ou fica Impedido. Uma ação e um teste de Força (Atletismo) contra sua CD liberta. As teias são inflamáveis: cada Cubo de 1,5 m queima em 1 rodada, causando 2d4 de dano de Fogo a quem começar o turno no fogo.",
 "zone_of_truth": "Você cria uma zona contra mentiras numa Esfera de 4,5 m de raio no alcance. Quem entrar pela primeira vez no turno ou começar o turno nela faz salvaguarda de Carisma; na falha, não consegue mentir deliberadamente ali. Você sabe quem passou ou falhou. A criatura sabe da magia e pode evitar responder, mas o que disser é verdade.",
}
